/**** Streaming API *****/

struct TA_APO_Stream {
   /* The bars this handle has an output for (see TA_APO_OutRange). */
   int outRangeBegIdx;
   int outRangeCount;
   /* The value(s) at the last bar the stream counted (see TA_APO_Value). */
   double cur_outReal;
   int optInFastPeriod;
   int optInSlowPeriod;
   TA_MAType optInMAType;
   TA_MA_Stream *sub0;
   TA_MA_Stream *sub1;
};

/* Private function, not in public API. */
static TA_RetCode TA_APO_StepImpl( struct TA_APO_Stream *sp, double inReal, double *outReal )
{
   double cur_tempBuffer = 0.0;
   double cur_outReal = 0.0;


   /* Pipeline the new bar through the sub-streams (batch tail order). */
   {
      TA_RetCode subRc = TA_MA_Update( sp->sub0, inReal, &cur_tempBuffer );
      if( subRc != TA_SUCCESS ) return subRc;
   }
   {
      TA_RetCode subRc = TA_MA_Update( sp->sub1, inReal, &cur_outReal );
      if( subRc != TA_SUCCESS ) return subRc;
   }
   /* Combine map (batch tail, per bar). */
   cur_outReal = cur_tempBuffer - cur_outReal;
   *outReal = cur_outReal;
   return TA_SUCCESS;
}

