#include <stddef.h>
#include <stdlib.h>

/* Pull in TA_LIB_API so the TA_GetVersion* functions are annotated with
 * __declspec(dllexport) on Windows. Without this include the definitions are
 * compiled without the export attribute and are absent from ta-lib.dll while
 * still present on Linux/macOS (see issue #57).
 */
#include "ta_common.h"

/* Package versioning. Written by scripts/sync.py from VERSION; do not edit. */
#define MAJOR "0"
#define MINOR "8"
#define PATCH "3"

/* Deprecated: Use PATCH instead. */
#define BUILD PATCH

/* Nothing to modify below this line. */

#define TA_VERSION_DT "(" __DATE__ " " __TIME__ ")"

const char  *TA_GetVersionString( void )
{
	return MAJOR "." MINOR "." PATCH " " TA_VERSION_DT;
}

const char *TA_GetVersionMajor( void )
{
   return MAJOR;
}

const char *TA_GetVersionMinor( void )
{
   return MINOR;
}

const char *TA_GetVersionPatch( void )
{
   return PATCH;
}

const char *TA_GetVersionBuild( void )
{
   /* Deprecated: No further support for Build versioning.
    * Package versioning are now only MAJOR.MINOR.PATCH
    */
   return PATCH;
}

const char *TA_GetVersionExtra( void )
{
   /* Deprecated: No further support for Extra versioning.
    * Package versioning are now only MAJOR.MINOR.PATCH
    */
   return "";
}

const char *TA_GetVersionDate( void )
{
   return __DATE__;
}

const char *TA_GetVersionTime( void )
{
   return __TIME__;
}

